// Parse Claude response into structured fields with audience routing.

const raw = $input.first().json.content?.[0]?.text || $input.first().json?.text || '';
if (!raw) {
  throw new Error('Claude returned empty response');
}

function extract(start, end) {
  const re = new RegExp(`<<<${start}>>>([\\s\\S]*?)<<<${end}>>>`, 'i');
  const m = raw.match(re);
  return m ? m[1].trim() : '';
}

const metaStr = extract('META', 'BLOG_MARKDOWN');
const blogMd = extract('BLOG_MARKDOWN', 'LINKEDIN_SHOWCASE');
const linkedinPost = extract('LINKEDIN_SHOWCASE', 'DRAFTS');
const draftsStr = extract('DRAFTS', 'END');

let meta = {};
try { meta = JSON.parse(metaStr); } catch (e) {
  throw new Error('Failed to parse META JSON: ' + e.message + '\nGot: ' + metaStr.slice(0, 200));
}

let drafts = {};
try { drafts = JSON.parse(draftsStr); } catch (e) {
  drafts = { _parse_error: e.message };
}

// Read audience+language from input (fallback to meta, fallback to defaults)
const input = $input.first().json;
const audience = (meta.audience || input.body?.audience || input.audience || 'growth').toLowerCase();
const language = (meta.language || input.body?.language || input.language || 'pt').toLowerCase();

// Map audience -> LinkedIn target page
const targetMap = {
  growth: { slug: 'anuvia-growth', name: 'Anuvia Growth' },
  engineering: { slug: 'anuvia-engineering', name: 'Anuvia Engineering' },
  institutional: { slug: 'anuvia-ltda', name: 'Anuvia (master)' }
};
const linkedinTarget = targetMap[audience] || targetMap.growth;

// Sanitize slug
let slug = (meta.slug || meta.title || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 60);
if (!slug) slug = 'post-' + Date.now();

// Build markdown with frontmatter (audience+language as tags)
const today = new Date().toISOString().slice(0, 10);
const userTags = (meta.tags || []).filter(Boolean);
const allTags = Array.from(new Set([...userTags, audience, language])); // dedupe
const frontmatter = `---
title: "${(meta.title || '').replace(/"/g, '\\"')}"
slug: ${slug}
date: ${today}
author: Mila Vernazza
audience: ${audience}
language: ${language}
${meta.subtitle ? `subtitle: "${meta.subtitle.replace(/"/g, '\\"')}"\n` : ''}excerpt: "${(meta.excerpt || '').replace(/"/g, '\\"')}"
tags:
${allTags.map(t => '  - ' + t).join('\n')}
---

`;

const fullMd = frontmatter + blogMd + '\n';
const contentB64 = Buffer.from(fullMd, 'utf-8').toString('base64');

return [{
  json: {
    meta,
    audience,
    language,
    linkedin_target: linkedinTarget.slug,
    linkedin_target_name: linkedinTarget.name,
    slug,
    blog_path: `posts/${slug}.md`,
    blog_content_b64: contentB64,
    blog_url: `https://blog.anuvia.com.br/blog/${slug}`,
    commit_message: `blog(${audience}/${language}): ${meta.title || slug}`,
    linkedin_post: linkedinPost,
    drafts,
  }
}];

