// Build Slack DM blocks with status + manual-channel drafts.

const parse = $('Parse Claude bundle').first().json;
const meta = parse.meta || {};
const drafts = parse.drafts || {};
const audience = parse.audience;
const language = parse.language;
const targetName = parse.linkedin_target_name;
const blogUrl = parse.blog_url;

let githubOk = false, makeOk = false, githubError = '', makeError = '';
try {
  const ghOut = $('GitHub: commit blog .md').first().json;
  githubOk = !!(ghOut && (ghOut.content || ghOut.commit));
  if (!githubOk) githubError = ghOut?.message || JSON.stringify(ghOut).slice(0, 200);
} catch (e) { githubError = e.message; }
try {
  const mkOut = $('Make webhook: LinkedIn router').first().json;
  makeOk = !mkOut?.error;
  if (!makeOk) makeError = mkOut?.error || JSON.stringify(mkOut).slice(0, 200);
} catch (e) { makeError = e.message; }

function codeBlock(t) { return '```' + (t || '(vazio)') + '```'; }
function trunc(s, n) { return (s || '').length > n ? s.slice(0, n) + '…' : (s || ''); }

const tagEmoji = audience === 'engineering' ? 'ENG' : audience === 'institutional' ? 'INST' : 'GROWTH';
const langEmoji = (language || 'pt').toUpperCase();

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `Content multiplier — ${tagEmoji} / ${langEmoji}`, emoji: false } },
  { type: 'context', elements: [ { type: 'mrkdwn', text: `*Tópico:* ${trunc(meta.title || '?', 80)} · *Target:* ${targetName}` } ] },
  { type: 'divider' },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Auto-publicados:* ${githubOk ? 'OK' : 'X'} Blog · ${makeOk ? 'OK' : 'X'} LinkedIn ${targetName}\n${githubOk ? `<${blogUrl}|${blogUrl}>` : `Blog falhou: ${trunc(githubError, 200)}`}\n${makeOk ? `LinkedIn ${targetName} enfileirado no Make` : `Make falhou: ${trunc(makeError, 200)}`}`
    }
  },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: '*Drafts pra revisar e postar manual*' } },
  { type: 'section', text: { type: 'mrkdwn', text: `*LinkedIn pessoal* (Mila)\n${codeBlock(trunc(drafts.linkedin_personal, 1800))}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Twitter / X*\n${codeBlock(trunc(drafts.twitter, 280))}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Instagram caption*\n${codeBlock(trunc(drafts.instagram_caption, 1800))}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Newsletter*\nSubject: \`${trunc(drafts.newsletter_subject, 100)}\`\n${codeBlock(trunc(drafts.newsletter_body, 2200))}` } },
];

return [{
  json: {
    channel: 'D0B2GR0HA2J',
    text: `Content multiplier ${tagEmoji}/${langEmoji} — "${trunc(meta.title || '?', 60)}" — blog ${githubOk ? 'publicado' : 'falhou'} · LinkedIn ${targetName} ${makeOk ? 'enfileirado' : 'falhou'} · 4 drafts`,
    blocks,
  }
}];
